// GENERATED by scripts/build-courses.ts from src/lib/courses/content — edit those files, then run: npm run courses
import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"Businesses create goods and services that people need and want. Let's see how they work.","blocks":[{"t":"p","text":"A business is an organization that provides goods or services in exchange for money, usually to earn a profit. Profit = revenue − expenses."},{"t":"key","text":"Businesses serve customers, create jobs, pay taxes and drive innovation. Successful businesses solve a problem or meet a need better than competitors."},{"t":"p","text":"Business sectors: producers make goods, service businesses provide services (haircuts, software), and retailers sell goods to consumers. Nonprofits serve a mission rather than earning profit for owners."},{"t":"p","text":"Key business functions: management, marketing, finance, operations (production) and human resources."},{"t":"ex","problem":"A bakery earns $8,000 in sales and has $5,500 in expenses this month. What's its profit?","steps":["Profit = revenue − expenses"],"answer":"$2,500"}]},{"say":"How a business is owned affects who controls it, who pays taxes, and who's responsible for its debts.","blocks":[{"t":"key","text":"Forms of business ownership:"},{"t":"list","items":["Sole proprietorship: one owner, easy to start, but the owner has unlimited liability (personally responsible for all debts).","Partnership: two or more owners share profits, decisions and liability.","Corporation: a separate legal entity owned by shareholders. Owners have limited liability, but it's more complex and is taxed separately.","LLC (limited liability company): combines limited liability with simpler taxes; popular with small businesses."]},{"t":"p","text":"Franchises let you open a business using an established brand's name and system (like many fast-food restaurants) in exchange for fees."}]}],[{"say":"Marketing is how a business connects its product with customers. The 4 P's are the core toolkit.","blocks":[{"t":"key","text":"The marketing mix (4 P's):"},{"t":"list","items":["Product: what you sell, including features, quality and branding.","Price: how much you charge, based on costs, competitors and customer value.","Place: where and how customers buy it (stores, online, distribution).","Promotion: how you communicate with customers (ads, social media, sales, public relations)."]},{"t":"p","text":"A brand is the name, logo and reputation that make a product recognizable. A unique selling proposition (USP) explains why a product is different and better."},{"t":"ex","problem":"A company launches eco-friendly sneakers sold only online for $90 with Instagram ads. Identify the 4 P's.","steps":["Product: eco-friendly sneakers. Price: $90"],"answer":"Place: online; Promotion: Instagram ads"}]},{"say":"Great businesses know their customers deeply. Market research helps you find and understand them.","blocks":[{"t":"key","text":"A target market is the specific group of customers a business aims to serve. Businesses divide markets into segments by demographics (age, income), geography, psychographics (values, lifestyle) and behavior (buying habits)."},{"t":"p","text":"Market research gathers information: primary research (surveys, interviews, focus groups) and secondary research (existing data and reports)."},{"t":"p","text":"Customer needs and wants guide product design. Customer service and customer loyalty keep people coming back; it's usually cheaper to keep a customer than to find a new one."}]}],[{"say":"Money is the lifeblood of a business. Understanding finances helps you make smart decisions.","blocks":[{"t":"key","text":"Financial statements:"},{"t":"list","items":["Income statement: revenue, expenses and profit over a period.","Balance sheet: assets (what the business owns), liabilities (what it owes) and owner's equity. Assets = liabilities + equity.","Cash flow statement: money coming in and going out."]},{"t":"p","text":"Break-even point: the sales needed to cover all costs. Break-even units = fixed costs ÷ (price − variable cost per unit)."},{"t":"ex","problem":"Fixed costs are $2,000, the price is $25, and variable cost is $15 per unit. Find the break-even point.","steps":["Each unit contributes 25 − 15 = $10"],"answer":"2,000 ÷ 10 = 200 units"},{"t":"p","text":"Businesses raise money through owners' savings, loans, investors (like venture capital) and crowdfunding."}]},{"say":"Managers organize people and resources to reach goals. Leaders inspire people to follow.","blocks":[{"t":"key","text":"The functions of management: planning (setting goals), organizing (arranging resources), leading (motivating people) and controlling (measuring results and correcting course)."},{"t":"p","text":"Leadership styles: autocratic (leader decides alone), democratic (team input) and laissez-faire (team has freedom). Good leaders adapt their style to the situation."},{"t":"p","text":"SMART goals are Specific, Measurable, Achievable, Relevant and Time-bound."},{"t":"p","text":"Business ethics means making decisions that are honest and fair to customers, employees, communities and the environment. Corporate social responsibility is a company's commitment to positive social impact."}]}],[{"say":"Entrepreneurs turn ideas into businesses. It takes creativity, risk-taking and persistence.","blocks":[{"t":"key","text":"Entrepreneurs spot opportunities by noticing problems, changes in trends or unmet needs. A good business idea solves a real problem for a specific group of customers who will pay for it."},{"t":"p","text":"Validate an idea before investing heavily: talk to potential customers, research competitors, and test a minimum viable product (MVP), a simple version to gather feedback."},{"t":"p","text":"Risks include losing money and time; rewards include independence, profit and impact. Many successful entrepreneurs failed first and learned from it."},{"t":"p","text":"Legal steps include choosing a business structure, registering the business name, getting licenses and permits, and understanding taxes."}]},{"say":"A business plan is a roadmap for your business. It helps you think clearly and attract investors.","blocks":[{"t":"key","text":"A business plan typically includes:"},{"t":"list","items":["Executive summary: a short overview of the whole plan.","Company description and mission statement.","Market analysis: target customers and competitors.","Products or services.","Marketing and sales strategy.","Operations and management team.","Financial plan: startup costs, projected revenue and break-even analysis."]},{"t":"p","text":"A SWOT analysis evaluates Strengths and Weaknesses (internal) and Opportunities and Threats (external)."},{"t":"p","text":"A pitch is a short, persuasive presentation of your business to investors or partners."}]}]];
export default text;
